/*!
 * Mermaid.js Offline Bundle for AU Notes HTML Artifacts & Visual Engine
 * Supports: flowchart/graph (TD, TB, LR, RL), sequenceDiagram, mindmap, stateDiagram, pie, timeline
 * Features: Automatic DAG layout, collision-free node geometry, responsive SVG, light/dark themes, graceful error handling
 */
(function (global) {
  "use strict";

  var config = {
    startOnLoad: true,
    theme: "default",
    securityLevel: "loose"
  };

  function escapeXml(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function cleanLabel(raw) {
    var t = String(raw || "").trim();
    if ((t.startsWith('"') && t.endsWith('"')) || (t.startsWith("'") && t.endsWith("'"))) {
      t = t.substring(1, t.length - 1);
    }
    return t.replace(/<br\s*\/?>/gi, " / ").trim();
  }

  function wrapLines(text, maxChars) {
    var words = String(text || "").split(/\s+/);
    var lines = [];
    var current = "";
    words.forEach(function (w) {
      if (!current) current = w;
      else if ((current + " " + w).length <= maxChars) current += " " + w;
      else {
        lines.push(current);
        current = w;
      }
    });
    if (current) lines.push(current);
    return lines.length > 0 ? lines.slice(0, 3) : [""];
  }

  function parseNodeToken(token, nodesMap) {
    var raw = token.trim();
    if (!raw) return null;
    var m =
      raw.match(/^([A-Za-z0-9_.-]+)\s*\(\(\s*([\s\S]*?)\s*\)\)$/) ||
      raw.match(/^([A-Za-z0-9_.-]+)\s*\(\[\s*([\s\S]*?)\s*\]\)$/) ||
      raw.match(/^([A-Za-z0-9_.-]+)\s*\[\[\s*([\s\S]*?)\s*\]\]$/) ||
      raw.match(/^([A-Za-z0-9_.-]+)\s*\{\{\s*([\s\S]*?)\s*\}\}$/) ||
      raw.match(/^([A-Za-z0-9_.-]+)\s*\{\s*([\s\S]*?)\s*\}$/) ||
      raw.match(/^([A-Za-z0-9_.-]+)\s*\(\s*([\s\S]*?)\s*\)$/) ||
      raw.match(/^([A-Za-z0-9_.-]+)\s*\[\s*([\s\S]*?)\s*\]$/);

    var shape = "rect";
    var id = raw;
    var label = raw;
    if (m) {
      id = m[1].trim();
      label = cleanLabel(m[2]);
      if (raw.indexOf("((") > -1) shape = "circle";
      else if (raw.indexOf("{") > -1) shape = "diamond";
      else if (raw.indexOf("(") > -1) shape = "round";
    } else {
      id = raw.replace(/[^A-Za-z0-9_.-]/g, "_");
      label = cleanLabel(raw);
    }

    if (!nodesMap[id]) {
      nodesMap[id] = { id: id, label: label || id, shape: shape };
    } else if (label && label !== id && nodesMap[id].label === id) {
      nodesMap[id].label = label;
      nodesMap[id].shape = shape;
    }
    return id;
  }

  function renderFlowchart(code, isDark) {
    var lines = code.split(/\r?\n/).map(function (l) { return l.trim(); }).filter(function (l) {
      return l && !l.startsWith("%%") && !l.startsWith("classDef ") && !l.startsWith("class ") && !l.startsWith("style ") && !l.startsWith("linkStyle ");
    });
    if (lines.length === 0) throw new Error("Empty flowchart");

    var header = lines[0];
    var dirMatch = header.match(/^(?:graph|flowchart)\s+(TB|TD|BT|RL|LR)\b/i);
    var direction = dirMatch ? dirMatch[1].toUpperCase() : "TD";
    var isHorizontal = direction === "LR" || direction === "RL";

    var nodesMap = {};
    var edges = [];

    for (var i = 1; i < lines.length; i++) {
      var line = lines[i];
      if (/^subgraph\b/i.test(line) || /^end\b/i.test(line) || /^direction\b/i.test(line)) continue;

      // Split chained arrows like A --> B --> C
      var arrowRegex = /\s*(?:--\s*([^->|]+?)\s*-->|-\.\s*([^.>-]+?)\s*\.->|==\s*([^=>]+?)\s*==>|--+>\s*\|([^|]*)\|\s*|-\.+->\s*\|([^|]*)\|\s*|==+>\s*\|([^|]*)\|\s*|--+>|-\.+->|==+>|---)\s*/g;
      var parts = [];
      var labels = [];
      var lastIdx = 0;
      var match;
      while ((match = arrowRegex.exec(line)) !== null) {
        parts.push(line.substring(lastIdx, match.index));
        var edgeLbl = match[1] || match[2] || match[3] || match[4] || match[5] || match[6] || "";
        labels.push(cleanLabel(edgeLbl));
        lastIdx = match.index + match[0].length;
      }
      if (parts.length > 0) {
        parts.push(line.substring(lastIdx));
        for (var k = 0; k < parts.length - 1; k++) {
          var fromId = parseNodeToken(parts[k], nodesMap);
          var toId = parseNodeToken(parts[k + 1], nodesMap);
          if (fromId && toId) {
            edges.push({ from: fromId, to: toId, label: labels[k] || "" });
          }
        }
      } else {
        parseNodeToken(line, nodesMap);
      }
    }

    var nodeIds = Object.keys(nodesMap);
    if (nodeIds.length === 0) throw new Error("No valid flowchart nodes found");

    // Assign topological ranks
    var inDegree = {};
    var adj = {};
    nodeIds.forEach(function (id) { inDegree[id] = 0; adj[id] = []; });
    edges.forEach(function (e) {
      if (adj[e.from]) adj[e.from].push(e.to);
      inDegree[e.to] = (inDegree[e.to] || 0) + 1;
    });

    var rank = {};
    var queue = [];
    nodeIds.forEach(function (id) {
      if (!inDegree[id]) {
        rank[id] = 0;
        queue.push(id);
      }
    });
    if (queue.length === 0) {
      rank[nodeIds[0]] = 0;
      queue.push(nodeIds[0]);
    }
    var visited = {};
    while (queue.length > 0) {
      var u = queue.shift();
      visited[u] = true;
      (adj[u] || []).forEach(function (v) {
        var nextRank = (rank[u] || 0) + 1;
        if (rank[v] === undefined || rank[v] < nextRank) {
          rank[v] = Math.min(nodeIds.length, nextRank);
        }
        if (!visited[v] && queue.indexOf(v) === -1) {
          queue.push(v);
        }
      });
    }
    nodeIds.forEach(function (id, idx) {
      if (rank[id] === undefined) rank[id] = idx;
    });

    var layers = {};
    var maxRank = 0;
    nodeIds.forEach(function (id) {
      var r = rank[id];
      if (r > maxRank) maxRank = r;
      if (!layers[r]) layers[r] = [];
      layers[r].push(nodesMap[id]);
    });

    var nodeW = 168;
    var nodeH = 54;
    var gapMain = isHorizontal ? 86 : 68;
    var gapCross = isHorizontal ? 34 : 38;

    var maxPerLayer = 1;
    Object.keys(layers).forEach(function (r) {
      if (layers[r].length > maxPerLayer) maxPerLayer = layers[r].length;
    });

    var W = isHorizontal
      ? Math.max(480, (maxRank + 1) * (nodeW + gapMain) + 60)
      : Math.max(460, maxPerLayer * (nodeW + gapCross) + 60);
    var H = isHorizontal
      ? Math.max(240, maxPerLayer * (nodeH + gapCross) + 60)
      : Math.max(260, (maxRank + 1) * (nodeH + gapMain) + 60);

    Object.keys(layers).forEach(function (rStr) {
      var r = Number(rStr);
      var list = layers[r];
      list.forEach(function (node, idx) {
        if (isHorizontal) {
          var totalLayerH = list.length * nodeH + (list.length - 1) * gapCross;
          var startY = (H - totalLayerH) / 2;
          node.x = 36 + r * (nodeW + gapMain);
          node.y = startY + idx * (nodeH + gapCross);
        } else {
          var totalLayerW = list.length * nodeW + (list.length - 1) * gapCross;
          var startX = (W - totalLayerW) / 2;
          node.x = startX + idx * (nodeW + gapCross);
          node.y = 32 + r * (nodeH + gapMain);
        }
      });
    });

    var bgNode = isDark ? "#23232B" : "#FFFFFF";
    var borderNode = isDark ? "#FB923C" : "#EA580C";
    var textCol = isDark ? "#F4F4F6" : "#18181B";
    var edgeCol = isDark ? "#A1A1AA" : "#52525B";
    var badgeBg = isDark ? "#18181E" : "#FAF8F5";

    var svg = [];
    svg.push(
      '<defs>' +
        '<marker id="m_arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6.5" markerHeight="6.5" orient="auto-start-reverse">' +
          '<path d="M 0 1 L 9 5 L 0 9 z" fill="' + edgeCol + '"/>' +
        '</marker>' +
      '</defs>'
    );

    // Edges
    edges.forEach(function (e) {
      var n1 = nodesMap[e.from];
      var n2 = nodesMap[e.to];
      if (!n1 || !n2) return;
      var x1, y1, x2, y2;
      if (isHorizontal) {
        x1 = n1.x + nodeW;
        y1 = n1.y + nodeH / 2;
        x2 = n2.x;
        y2 = n2.y + nodeH / 2;
      } else {
        x1 = n1.x + nodeW / 2;
        y1 = n1.y + nodeH;
        x2 = n2.x + nodeW / 2;
        y2 = n2.y;
      }
      var mx = (x1 + x2) / 2;
      var my = (y1 + y2) / 2;
      var d = isHorizontal
        ? "M " + x1 + " " + y1 + " C " + mx + " " + y1 + ", " + mx + " " + y2 + ", " + x2 + " " + y2
        : "M " + x1 + " " + y1 + " C " + x1 + " " + my + ", " + x2 + " " + my + ", " + x2 + " " + y2;

      svg.push('<path d="' + d + '" fill="none" stroke="' + edgeCol + '" stroke-width="2" marker-end="url(#m_arrow)"/>');
      if (e.label) {
        var lw = Math.min(130, e.label.length * 6.8 + 14);
        svg.push(
          '<rect x="' + (mx - lw / 2).toFixed(1) + '" y="' + (my - 10).toFixed(1) + '" width="' + lw.toFixed(1) + '" height="19" rx="6" fill="' + badgeBg + '" stroke="' + edgeCol + '" stroke-width="0.8"/>' +
          '<text x="' + mx.toFixed(1) + '" y="' + (my + 3).toFixed(1) + '" text-anchor="middle" fill="' + textCol + '" font-family="system-ui,-apple-system,sans-serif" font-size="10.5" font-weight="600">' +
          escapeXml(e.label.substring(0, 20)) + '</text>'
        );
      }
    });

    // Nodes
    nodeIds.forEach(function (id, idx) {
      var n = nodesMap[id];
      var isRoot = idx === 0;
      var fill = isRoot ? (isDark ? "#EA580C" : "#EA580C") : bgNode;
      var txt = isRoot ? "#FFFFFF" : textCol;
      var rx = n.shape === "circle" ? (nodeH / 2) : n.shape === "round" ? 20 : 12;

      if (n.shape === "diamond") {
        var cx = n.x + nodeW / 2;
        var cy = n.y + nodeH / 2;
        var pts = [
          cx + "," + (n.y - 6),
          (n.x + nodeW + 8) + "," + cy,
          cx + "," + (n.y + nodeH + 6),
          (n.x - 8) + "," + cy
        ].join(" ");
        svg.push('<polygon points="' + pts + '" fill="' + fill + '" stroke="' + borderNode + '" stroke-width="2"/>');
      } else {
        svg.push(
          '<rect x="' + n.x.toFixed(1) + '" y="' + n.y.toFixed(1) + '" width="' + nodeW + '" height="' + nodeH + '" rx="' + rx + '" fill="' + fill + '" stroke="' + borderNode + '" stroke-width="2"/>'
        );
      }

      var wrapped = wrapLines(n.label, 20);
      var lineStart = n.y + nodeH / 2 - ((wrapped.length - 1) * 14) / 2 + 4;
      wrapped.forEach(function (ln, lIdx) {
        svg.push(
          '<text x="' + (n.x + nodeW / 2).toFixed(1) + '" y="' + (lineStart + lIdx * 14).toFixed(1) + '" text-anchor="middle" fill="' + txt + '" font-family="system-ui,-apple-system,sans-serif" font-size="12" font-weight="700">' +
          escapeXml(ln) + '</text>'
        );
      });
    });

    return '<svg viewBox="0 0 ' + W + ' ' + H + '" style="width:100%;height:auto;display:block;" xmlns="http://www.w3.org/2000/svg">' + svg.join("") + '</svg>';
  }

  function renderSequenceDiagram(code, isDark) {
    var lines = code.split(/\r?\n/).map(function (l) { return l.trim(); }).filter(function (l) { return l && !l.startsWith("%%"); });
    var participants = [];
    var partMap = {};
    var messages = [];

    function ensureParticipant(id, label) {
      var cleanId = id.trim();
      if (!partMap[cleanId]) {
        var obj = { id: cleanId, label: cleanLabel(label || cleanId) };
        partMap[cleanId] = obj;
        participants.push(obj);
      }
    }

    for (var i = 1; i < lines.length; i++) {
      var l = lines[i];
      var pm = l.match(/^(?:participant|actor)\s+([A-Za-z0-9_.-]+)(?:\s+as\s+(.+))?$/i);
      if (pm) {
        ensureParticipant(pm[1], pm[2] || pm[1]);
        continue;
      }
      var mm = l.match(/^([A-Za-z0-9_.-]+)\s*(-?->>?|-->>?|-x)\s*([A-Za-z0-9_.-]+)\s*:\s*(.+)$/);
      if (mm) {
        ensureParticipant(mm[1], mm[1]);
        ensureParticipant(mm[3], mm[3]);
        messages.push({
          from: mm[1].trim(),
          to: mm[3].trim(),
          dashed: mm[2].indexOf("--") === 0,
          text: cleanLabel(mm[4])
        });
      }
    }

    if (participants.length === 0) throw new Error("No sequence participants found");
    var colSpan = 175;
    var W = Math.max(460, participants.length * colSpan + 60);
    var H = Math.max(240, 120 + messages.length * 52);

    var bgBox = isDark ? "#23232B" : "#FFFFFF";
    var textCol = isDark ? "#F4F4F6" : "#18181B";
    var accent = "#EA580C";
    var lineCol = isDark ? "#71717A" : "#64748B";

    var svg = [
      '<defs><marker id="seq_arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M 0 1 L 9 5 L 0 9 z" fill="' + accent + '"/></marker></defs>'
    ];

    participants.forEach(function (p, idx) {
      p.cx = 50 + idx * colSpan + 60;
      svg.push(
        '<line x1="' + p.cx + '" y1="56" x2="' + p.cx + '" y2="' + (H - 28) + '" stroke="' + lineCol + '" stroke-dasharray="4 4" stroke-width="1.5"/>' +
        '<rect x="' + (p.cx - 62) + '" y="16" width="124" height="38" rx="10" fill="' + bgBox + '" stroke="' + accent + '" stroke-width="2"/>' +
        '<text x="' + p.cx + '" y="39" text-anchor="middle" fill="' + textCol + '" font-family="system-ui,-apple-system,sans-serif" font-size="12" font-weight="700">' + escapeXml(p.label.substring(0, 16)) + '</text>'
      );
    });

    messages.forEach(function (m, idx) {
      var p1 = partMap[m.from];
      var p2 = partMap[m.to];
      if (!p1 || !p2) return;
      var y = 92 + idx * 50;
      var mx = (p1.cx + p2.cx) / 2;
      svg.push(
        '<line x1="' + p1.cx + '" y1="' + y + '" x2="' + p2.cx + '" y2="' + y + '" stroke="' + accent + '" stroke-width="2" ' + (m.dashed ? 'stroke-dasharray="5 4" ' : '') + 'marker-end="url(#seq_arrow)"/>' +
        '<text x="' + mx + '" y="' + (y - 8) + '" text-anchor="middle" fill="' + textCol + '" font-family="system-ui,-apple-system,sans-serif" font-size="11.5" font-weight="600">' + escapeXml(m.text.substring(0, 34)) + '</text>'
      );
    });

    return '<svg viewBox="0 0 ' + W + ' ' + H + '" style="width:100%;height:auto;display:block;" xmlns="http://www.w3.org/2000/svg">' + svg.join("") + '</svg>';
  }

  function renderMindmap(code, isDark) {
    var rawLines = code.split(/\r?\n/).filter(function (l) { return l.trim() && !l.trim().startsWith("%%") && !/^mindmap\b/i.test(l.trim()); });
    if (rawLines.length === 0) throw new Error("Empty mindmap");

    var items = rawLines.map(function (l) {
      var indent = l.search(/\S|$/);
      var txt = l.trim().replace(/^root\s*\(\((.*)\)\)$/i, "$1").replace(/^[\(\[\{]+|[\)\]\}]+$/g, "");
      return { indent: indent, label: cleanLabel(txt) };
    });

    var root = items[0];
    var branches = items.slice(1);
    var W = 640;
    var H = Math.max(260, Math.ceil(branches.length / 2) * 58 + 110);
    var cx = W / 2;
    var cy = H / 2;
    var textCol = isDark ? "#F4F4F6" : "#18181B";
    var cardBg = isDark ? "#23232B" : "#FFFFFF";
    var palette = ["#EA580C", "#2563EB", "#16A34A", "#9333EA", "#CA8A04", "#0D9488"];

    var svg = [];
    branches.forEach(function (b, idx) {
      var leftSide = idx % 2 === 0;
      var row = Math.floor(idx / 2);
      var totalRows = Math.max(1, Math.ceil(branches.length / 2));
      var by = 46 + row * ((H - 92) / Math.max(1, totalRows - 1 || 1));
      if (totalRows === 1) by = cy;
      var bx = leftSide ? 95 : W - 95;
      var col = palette[idx % palette.length];
      var d = "M " + cx + " " + cy + " C " + ((cx + bx) / 2) + " " + cy + ", " + ((cx + bx) / 2) + " " + by + ", " + bx + " " + by;
      svg.push(
        '<path d="' + d + '" fill="none" stroke="' + col + '" stroke-width="2.5"/>' +
        '<rect x="' + (bx - 78) + '" y="' + (by - 19) + '" width="156" height="38" rx="12" fill="' + cardBg + '" stroke="' + col + '" stroke-width="2"/>' +
        '<text x="' + bx + '" y="' + (by + 4) + '" text-anchor="middle" fill="' + textCol + '" font-family="system-ui,-apple-system,sans-serif" font-size="11.5" font-weight="700">' + escapeXml(b.label.substring(0, 20)) + '</text>'
      );
    });

    svg.push(
      '<rect x="' + (cx - 86) + '" y="' + (cy - 24) + '" width="172" height="48" rx="24" fill="#EA580C"/>' +
      '<text x="' + cx + '" y="' + (cy + 5) + '" text-anchor="middle" fill="#FFFFFF" font-family="system-ui,-apple-system,sans-serif" font-size="13" font-weight="800">' + escapeXml(root.label.substring(0, 20)) + '</text>'
    );

    return '<svg viewBox="0 0 ' + W + ' ' + H + '" style="width:100%;height:auto;display:block;" xmlns="http://www.w3.org/2000/svg">' + svg.join("") + '</svg>';
  }

  function renderDiagramCode(rawCode) {
    var code = String(rawCode || "").trim();
    if (!code) throw new Error("Empty Mermaid syntax");
    var isDark =
      config.theme === "dark" ||
      document.documentElement.getAttribute("data-theme") === "dark" ||
      document.body.classList.contains("dark");

    var firstLine = code.split(/\r?\n/)[0].trim();
    if (/^(?:graph|flowchart)\b/i.test(firstLine)) {
      return renderFlowchart(code, isDark);
    }
    if (/^sequenceDiagram\b/i.test(firstLine)) {
      return renderSequenceDiagram(code, isDark);
    }
    if (/^mindmap\b/i.test(firstLine)) {
      return renderMindmap(code, isDark);
    }
    if (/^stateDiagram(?:-v2)?\b/i.test(firstLine)) {
      var converted = "flowchart TD\n" + code.split(/\r?\n/).slice(1).join("\n").replace(/\[\*\]/g, "StartNode([Start])");
      return renderFlowchart(converted, isDark);
    }
    // Check if it contains arrows anyway
    if (code.indexOf("-->") > -1 || code.indexOf("->") > -1) {
      return renderFlowchart("flowchart TD\n" + code, isDark);
    }
    throw new Error("Unsupported or invalid Mermaid syntax");
  }

  var mermaid = {
    initialize: function (opts) {
      if (opts && typeof opts === "object") {
        Object.assign(config, opts);
      }
    },
    render: function (id, code) {
      return new Promise(function (resolve, reject) {
        try {
          var svg = renderDiagramCode(code);
          resolve({ svg: svg });
        } catch (err) {
          reject(err);
        }
      });
    },
    run: function (opts) {
      var selector = (opts && opts.querySelector) || ".mermaid";
      var nodes = opts && opts.nodes ? opts.nodes : document.querySelectorAll(selector);
      Array.prototype.forEach.call(nodes, function (el) {
        if (el.getAttribute("data-processed") === "true") return;
        var raw = el.getAttribute("data-mermaid-code") || el.textContent || "";
        try {
          var svg = renderDiagramCode(raw);
          el.innerHTML = svg;
          el.setAttribute("data-processed", "true");
        } catch (err) {
          el.innerHTML =
            '<div class="au-chart-error" style="padding:20px;border-radius:14px;border:1.5px dashed #EF4444;background:rgba(239,68,68,0.08);color:#EF4444;font-family:system-ui,sans-serif;font-size:13px;text-align:center;font-weight:600;">' +
            'Chart could not be generated' +
            '</div>';
          el.setAttribute("data-processed", "error");
        }
      });
      return Promise.resolve();
    },
    init: function (opts, nodes) {
      return this.run({ nodes: nodes });
    }
  };

  if (typeof document !== "undefined") {
    document.addEventListener("DOMContentLoaded", function () {
      if (config.startOnLoad) mermaid.run();
    });
  }

  global.mermaid = mermaid;
})(typeof window !== "undefined" ? window : this);
